import{_ as n,C as i,o as d,c,j as t,a as s,E as a,a2 as r}from"./chunks/framework.sc8Z_ZE3.js";const b=JSON.parse('{"title":"Secret redaction","description":"","frontmatter":{},"headers":[],"relativePath":"security/redaction.md","filePath":"security/redaction.md"}'),l={name:"security/redaction.md"};function h(u,e,m,p,f,g){const o=i("Badge");return d(),c("div",null,[e[3]||(e[3]=t("h1",{id:"secret-redaction",tabindex:"-1"},[s("Secret redaction "),t("a",{class:"header-anchor",href:"#secret-redaction","aria-label":'Permalink to "Secret redaction"'},"​")],-1)),a(o,{type:"built",text:"Built"}),e[4]||(e[4]=r(' Secrets are replaced with <code>[redacted]</code> before text is stored, shown or sent on. Output from a developer&#39;s machine is redacted <strong>on the machine</strong>, before it leaves it.<h2 id="the-rule-sets" tabindex="-1">The rule sets <a class="header-anchor" href="#the-rule-sets" aria-label="Permalink to &quot;The rule sets&quot;">​</a></h2><ul><li><strong>The platform</strong> redacts everything it stores or shows with its full rule set, below.</li><li><strong>On the machine</strong>, every job output (test output, errors, tool output) is redacted before it is sent, with the same list of known secret forms the platform uses; the server redacts again when showing it.</li><li><strong>Transcripts</strong> are redacted on the machine before upload with the same list of known secret forms, plus rules for assignments, JSON fields, authorization headers and the whole output of secret commands and credential files. When the launcher&#39;s rules are missing, it sends nothing rather than sending unredacted text.</li><li>The <strong>session digest</strong> at the end of a session uses the same rules too, plus its own patterns; the platform redacts it once more on arrival.</li></ul><h2 id="what-the-platform-finds" tabindex="-1">What the platform finds <a class="header-anchor" href="#what-the-platform-finds" aria-label="Permalink to &quot;What the platform finds&quot;">​</a></h2><ul><li><strong>Secret names</strong> in structured values (JSON, YAML, settings): keys such as <code>password</code>, <code>secret</code>, <code>api_key</code>, <code>access_token</code>, <code>refresh_token</code>, <code>client_secret</code>, <code>private_key</code>, <code>authorization</code>, <code>cookie</code> or <code>credential</code>, also in camelCase, kebab-case or with dots (<code>db.password</code>, <code>KeystorePass</code>). In free text, such as tool output, the common names (<code>password</code>, <code>secret</code>, <code>api_key</code>, the token names) are found; <code>cookie</code>, <code>credential</code> and names ending in <code>Pass</code> are not yet.</li><li><strong>JSON and YAML</strong> values under those keys, and <strong>quoted values</strong> in assignments.</li><li><strong>URLs with credentials</strong>: <code>https://user:pass@host</code>, a user in front of a host, and JDBC URLs.</li><li><strong>Authorization headers</strong> with Bearer or Basic.</li><li><strong>Private key blocks</strong>.</li><li><strong>Known token forms</strong> (one shared list for the platform, job output, transcripts and the session digest): GitHub tokens (classic, fine-grained, OAuth, app and refresh), GitLab tokens, Slack bot and user tokens, AWS access keys, OpenAI and Anthropic API keys, Stripe keys, Google Cloud API keys and JSON Web Tokens.</li></ul><h2 id="where-it-applies" tabindex="-1">Where it applies <a class="header-anchor" href="#where-it-applies" aria-label="Permalink to &quot;Where it applies&quot;">​</a></h2><ul><li>the agent&#39;s tool output and the chat&#39;s trace;</li><li>session transcripts, when a Workspace switches them on, redacted on the machine;</li><li>the session digest the launcher sends at the end of a session;</li><li>corrections kept from pull request comments;</li><li>error messages from Git and connectors.</li></ul><h2 id="and-the-merge-gate" tabindex="-1">And the merge gate <a class="header-anchor" href="#and-the-merge-gate" aria-label="Permalink to &quot;And the merge gate&quot;">​</a></h2>',12)),t("p",null,[e[0]||(e[0]=s("Octryx AI's own repository runs gitleaks over every branch's commits before a merge. The launcher brings its own pinned gitleaks for runs on your machine; the ",-1)),e[1]||(e[1]=t("a",{href:"/docs/review-bot/#scanners"},"review bot",-1)),e[2]||(e[2]=s(" runs gitleaks on every pull request's changed files, and a committed secret fails its status. ",-1)),a(o,{type:"built",text:"Built"})]),e[5]||(e[5]=r('<h2 id="and-what-goes-to-a-model" tabindex="-1">And what goes to a model <a class="header-anchor" href="#and-what-goes-to-a-model" aria-label="Permalink to &quot;And what goes to a model&quot;">​</a></h2><p>What a model receives is checked separately, per content kind, with an action each Workspace chooses: see <a href="/docs/security/sensitive-content">Sensitive content handling</a>.</p><h2 id="limits" tabindex="-1">Limits <a class="header-anchor" href="#limits" aria-label="Permalink to &quot;Limits&quot;">​</a></h2><p>Redaction finds what its rules describe. A secret in an unusual form can pass. Do not rely on redaction instead of keeping secrets out of code.</p>',4))])}const w=n(l,[["render",h]]);export{b as __pageData,w as default};
